</template>

<script>
export default { name: 'EditAccess', props: { data: { type: Object, default: null } }, data() { return { form: { name:'',slug:'',description:'',type:'',price:'',currency:'USD',platform_link:'' }, detailsRows:[{key:'',value:''}], saving:false, errors:{}, thumbnailFile:null, thumbnailPreview:null, existingFiles:[], removedFileIds:[], selectedFiles:[], filePreviews:[] }; }, mounted(){this.initializeForm();}, methods:{ initializeForm(){if(!this.data)return; this.form={...this.form,name:this.data.name||'',slug:this.data.slug||'',description:this.data.description||'',type:this.data.type||'',price:this.data.price??'',currency:this.data.currency||'USD',platform_link:this.data.platform_link||''}; this.detailsRows=this.parseDetails(this.data.details); this.existingFiles=Array.isArray(this.data.files)?[...this.data.files]:[]; this.thumbnailPreview=this.getMediaUrl(this.data.thumbnail);}, parseDetails(d){if(!d)return[{key:'',value:''}];let p=d;if(typeof p==='string'){try{p=JSON.parse(p)}catch{return[{key:'',value:p}]}};return p&&typeof p==='object'&&!Array.isArray(p)?Object.keys(p).map(k=>({key:k,value:String(p[k]??'')})):[{key:'',value:''}];}, addDetail(){this.detailsRows.push({key:'',value:''});}, removeDetail(i){if(this.detailsRows.length>1)this.detailsRows.splice(i,1);}, getMediaUrl(m){if(!m)return null;if(typeof m==='string')return m;return m.url||m.path||m.src||null;}, handleThumbnail(e){const f=e.target.files?.[0];if(!f)return;this.thumbnailFile=f;this.thumbnailPreview=URL.createObjectURL(f);}, handleFiles(e){const fs=Array.from(e.target.files||[]);fs.forEach(f=>{this.selectedFiles.push(f);this.filePreviews.push({key:Date.now()+Math.random(),name:f.name,url:URL.createObjectURL(f),isVideo:f.type.startsWith('video/')});});e.target.value='';}, removeExistingFile(i){const f=this.existingFiles[i];if(f?.id)this.removedFileIds.push(f.id);this.existingFiles.splice(i,1);}, removeNewFile(k){const i=this.filePreviews.findIndex(f=>f.key===k);if(i>=0){URL.revokeObjectURL(this.filePreviews[i].url);this.filePreviews.splice(i,1);this.selectedFiles.splice(i,1);}}, validate(){this.errors={};if(!this.form.name.trim())this.errors.name='Access name is required.';return !Object.keys(this.errors).length;}, async save(){if(!this.data?.id){this.showToast('Access ID is missing.','error');return;}if(!this.validate())return;this.saving=true;try{const fd=new FormData();Object.entries({name:this.form.name.trim(),slug:this.form.slug.trim(),description:this.form.description.trim(),type:this.form.type.trim(),price:this.form.price||'0',currency:this.form.currency||'USD',platform_link:this.form.platform_link.trim()}).forEach(([k,v])=>fd.append(k,v));if(this.thumbnailFile)fd.append('thumbnail',this.thumbnailFile);this.selectedFiles.forEach(f=>fd.append('files',f));if(this.removedFileIds.length)fd.append('removedFileIds',JSON.stringify(this.removedFileIds));const details={};this.detailsRows.forEach(r=>{if(r.key.trim())details[r.key.trim()]=r.value;});if(Object.keys(details).length)fd.append('details',JSON.stringify(details));const response=await this.$apiPatch(`/Access/${this.data.id}`,'',fd);if(response){this.showToast('Access updated successfully','success');this.$emit('saved');}}catch(e){console.error(e);this.showToast(e?.response?.data?.message||'Failed to update Access','error');}finally{this.saving=false;}},close(){if(!this.saving)this.$emit('close');},showToast(m,t){if(this.$root.$refs.toast)this.$root.$refs.toast.showToast(m,t);}},beforeDestroy(){if(this.thumbnailPreview?.startsWith('blob:'))URL.revokeObjectURL(this.thumbnailPreview);this.filePreviews.forEach(f=>URL.revokeObjectURL(f.url));}};
</script>

