.field-label{@apply mb-1.5 block text-[11px] font-semibold text-slate-600}.field-input{@apply h-9 w-full border border-slate-200 bg-white px-3 text-xs text-slate-700 outline-none}.error-text{@apply mt-1 text-[10px] text-red-500}
</style>